/**
 * Boundary Checker
 * node starter/index.js
 */

const readline = require("node:readline");

function main() {
  const lines = [];
  const rl = readline.createInterface({ input: process.stdin });

function validateNumbers (a,b,c){
return Number.isFinite(Number(a)) && Number.isFinite(Number(b)) && Number.isFinite(Number(c));
}

function insideBoundaries (a,b){
return Number(a)<=Number(b);
}

  rl.on("line", (line) => {
    lines.push(line);
    if (lines.length < 3) return;
    valueToEvaluate = Number(lines[0]);
    lowerBoundary = Number(lines[1]);
    topBoundary = Number(lines[2]);


// catch number formatting error
if (!validateNumbers (valueToEvaluate, lowerBoundary, topBoundary)){
    process.stdout.write("ERROR: invalid number");
    rl.close();
}

// catch number range error
if (!insideBoundaries (lowerBoundary, topBoundary)){
    process.stdout.write("ERROR: invalid range");
    rl.close();
}

// Only parse validated values

if (validateNumbers (valueToEvaluate, lowerBoundary, topBoundary) && insideBoundaries (lowerBoundary, topBoundary)){

// out of range
if (valueToEvaluate > topBoundary || valueToEvaluate < lowerBoundary) {
    process.stdout.write("OUT OF RANGE");
    rl.close();
}

// in range
if (valueToEvaluate <= topBoundary && valueToEvaluate >= lowerBoundary) {
    process.stdout.write("IN RANGE");
    rl.close();
}

}
  });
}

main();
